<?php
 namespace Pterodactyl\Notifications; use Illuminate\Bus\Queueable; use Pterodactyl\Services\Dezerx\Emails; use Illuminate\Notifications\Notification; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; class AddedToServer extends Notification implements ShouldQueue { use Queueable; public object $server; public function __construct(array $server) { $this->server = (object) $server; } public function via(): array { return ['mail']; } public function toMail(): MailMessage { return Emails::apply(new MailMessage(), 'added-to-server', [ 'name' => (string) $this->server->user, 'server' => (string) $this->server->name, ], url('/server/' . $this->server->uuidShort)); } } 